public class ProductDTO { private Long idProduct; private String nombreProduct; private Double precio; private Double precioOferta; private Boolean enOferta; private Boolean estado; public Long getIdProduct(){return idProduct;} public void setIdProduct(Long v){idProduct=v;} public String getNombreProduct(){return nombreProduct;} public void setNombreProduct(String v){nombreProduct=v;} public Double getPrecio(){return precio;} public void setPrecio(Double v){precio=v;} public Double getPrecioOferta(){return precioOferta;} public void setPrecioOferta(Double v){precioOferta=v;} public Boolean getEnOferta(){return enOferta;} public void setEnOferta(Boolean v){enOferta=v;} public Boolean getEstado(){return estado;} public void setEstado(Boolean v){estado=v;} }
